// @ts-ignore: generated by opennextjs-cloudflare build
import nextWorker from "../.open-next/worker.js";
import { dispatchBillingRenewals, type BillingEnv } from "./workflows/billingRenew";
import PostalMime from "postal-mime";

// Workflow 클래스는 워커 메인 모듈에서 export돼야 wrangler.toml의 [[workflows]] 바인딩이 찾을 수 있다
export { BillingRenewWorkflow } from "./workflows/billingRenew";

interface Env extends BillingEnv {
  NEXT_PUBLIC_SUPABASE_URL: string;
  NEXT_PUBLIC_SUPABASE_ANON_KEY: string;
  INTERNAL_API_SECRET: string;
}

interface ScheduledEvent {
  cron: string;
}

/** Cloudflare 이메일 라우팅으로 받은 메일 (Email Workers) */
interface ForwardableEmailMessage {
  readonly from: string;
  readonly to: string;
  readonly raw: ReadableStream<Uint8Array>;
  readonly rawSize: number;
}

export default {
  ...nextWorker,

  // 네이버 예약 알림 메일 — n-{매장코드}@booking.flo-aide.com 으로 오면 읽어서 앱(/api/naver-mail)에 넘긴다
  // (예약 추가·취소·확인 필요 보관은 앱이 한다 — 워커는 메일을 풀어서 전달만)
  async email(message: ForwardableEmailMessage, env: Env, ctx: unknown) {
    try {
      const raw = await new Response(message.raw).arrayBuffer();
      const mail = await PostalMime.parse(raw);
      // 인터넷을 거치지 않고 같은 워커 안에서 앱(/api/naver-mail)을 바로 부른다
      // (메일 처리 중에 자기 도메인을 fetch하면 연결이 막혀 522가 난다)
      const req = new Request("https://www.flo-aide.com/api/naver-mail", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-internal-secret": env.INTERNAL_API_SECRET },
        body: JSON.stringify({
          to: message.to,
          from: message.from,
          subject: mail.subject ?? "",
          text: mail.text ?? "",
          html: mail.html ?? "",
        }),
      });
      const res: Response = await (nextWorker as { fetch: (r: Request, e: unknown, c: unknown) => Promise<Response> }).fetch(req, env, ctx);
      console.log(`[email] ${message.to} ← ${message.from} · ${res.status}:`, await res.text());
    } catch (err) {
      console.error("[email] 네이버 메일 처리 실패:", err);
    }
  },

  async scheduled(event: ScheduledEvent, env: Env, _ctx: unknown) {
    // Supabase 슬립 방지용 keep-alive
    await fetch(
      `${env.NEXT_PUBLIC_SUPABASE_URL}/rest/v1/companies?select=id&limit=1`,
      {
        headers: {
          apikey: env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
          Authorization: `Bearer ${env.NEXT_PUBLIC_SUPABASE_ANON_KEY}`,
        },
      }
    );

    // 매일 18:00 UTC(KST 03:00) — 체험 종료·구독 만료된 매장마다 정기결제 Workflow를 하나씩 시작
    // (결제/재시도/강등은 src/workflows/billingRenew.ts에서 구독별로 따로, 단계별 결과를 기억하며 처리)
    if (event.cron === "0 18 * * *") {
      try {
        await dispatchBillingRenewals(env);
      } catch (err) {
        console.error("[scheduled] billing-renew dispatch 실패:", err);
        throw err;
      }
    }

    // 매일 16:00 UTC(KST 01:00) — 예약일이 지났는데 미확정 상태인 예약 자동 완료 처리
    if (event.cron === "0 16 * * *") {
      try {
        const res = await fetch("https://www.flo-aide.com/api/cron/auto-complete-reservations", {
          method: "POST",
          headers: { "x-internal-secret": env.INTERNAL_API_SECRET },
        });
        const body = await res.text();
        console.log(`[scheduled] auto-complete-reservations ${res.status}:`, body);
        // 실패를 크론 결과(Past Cron Events)에도 표시되게 한다
        if (!res.ok) throw new Error(`auto-complete-reservations 실패 (${res.status})`);
      } catch (err) {
        console.error("[scheduled] auto-complete-reservations 호출 실패:", err);
        throw err;
      }
    }
  },
};
